def beautifulSubstrings(s: str, k: int):
    vowels_set = {'a', 'e', 'i', 'o', 'u'}
    count = 0
    n = len(s)

    # 因為 s.length <= 1000，使用 O(n^2) 的雙重迴圈即可通過
    for i in range(n):
        vowels = 0
        consonants = 0
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # 檢查是否符合題目條件
            if vowels == consonants and (vowels * consonants) % k == 0:
                count += 1

    return count
