def findPrimePairs(n: int):
    if n < 4: return []

    # Sieve of Eratosthenes
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(n**0.5) + 1):
        if primes[i]:
            for j in range(i*i, n + 1, i):
                primes[j] = False

    res = []
    # x must be at most n//2 because x <= y and x+y = n
    for x in range(2, (n // 2) + 1):
        y = n - x
        if primes[x] and primes[y]:
            res.append([x, y])
    return res
